class CfB_M2_Zone extends DCLogic {
constructor(props) {
super(props);
this.state = { zone: 'ajuster', motif: null, error: false, saved: false };
}
renderVals() {
const st = this.state;
const changed = st.zone !== 'ajuster';
const labels = { surveiller: 'Surveiller', ajuster: 'Ajuster', riposter: 'Riposter' };
const zones = ['surveiller', 'ajuster', 'riposter'].map((k) => ({
label: labels[k], on: st.zone === k, off: st.zone !== k,
pick: () => this.setState({ zone: k, error: false, saved: false })
}));
const motifs = [['contexte', 'Information contextuelle'], ['erreur', 'Erreur de l’IA']].map(([k, l]) => ({
label: l, checked: st.motif === k,
pick: () => this.setState({ motif: k, error: false })
}));
return {
zones, motifs, changed, unchanged: !changed,
showError: st.error, saved: st.saved,
savedText: 'Zone retenue pour la suite : ' + labels[st.zone].toLowerCase() + ' (' + (st.motif === 'erreur' ? 'erreur de l’IA' : 'information contextuelle') + ').',
validate: () => { if (!st.motif) { this.setState({ error: true, saved: false }); } else { this.setState({ error: false, saved: true }); } }
};
}
}
