class CfB_M2_Revue extends DCLogic {
renderVals() {
const ch = (this.state && this.state.ch) || null;
const st = (on) => 'min-height: 48px; padding: 8px 20px; border-radius: 999px; font: inherit; cursor: pointer; ' + (on ? 'border: 0; background: #3A2131; color: #FFFFFF; font-weight: 700' : 'border: 2px solid #F1E6DE; background: #FFFFFF; color: #2A2522; font-weight: 500');
const choices = [['keep', 'Oui, elle tient'], ['adjust', 'En partie, à ajuster'], ['redo', 'Non, il faut la revoir'], ['early', 'Trop tôt pour le dire']].map(([k, l]) => ({ label: l, on: k === ch ? 'true' : 'false', style: st(k === ch), pick: () => this.setState({ ch: k }) }));
return { choices, isKeep: ch === 'keep', isRedo: ch === 'redo' || ch === 'adjust', isEarly: ch === 'early' };
}
}
